9	/**
10	 * Rejects a create-owner request once the effective registration day has already reached its
11	 * owner quota, before {@link BuildOwner} runs. The day counted is the adjusted business day
12	 * resolved by {@link ResolveRegistrationDate}, so weekend requests count against the Monday they
13	 * roll forward to. A day is full once {@value #DAILY_LIMIT} or more owners carry that
14	 * registration date, so the next one would exceed the cap. Rejects with 429 otherwise.
15	 */
16	public class EnsureDailyOwnerLimit {
17	
18	    /** Maximum owners that may be registered on a single day; the next create is rejected. */
19	    static final int DAILY_LIMIT = 100;
20	
21	    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
22	            throws DailyOwnerLimitException {
23	        long count = ownerRepository.countByRegistrationDate(registrationDate);
24	        if (count >= DAILY_LIMIT) {
25	            throw new DailyOwnerLimitException(registrationDate, count);
26	        }
27	    }
28	}
