3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.time.temporal.TemporalAdjusters;
6	
7	/**
8	 * Business-day rules for registration dates. A registration date must fall on a business
9	 * day (Monday–Friday); a Saturday or Sunday rolls forward to the following Monday.
10	 */
11	public final class BusinessDay {
12	
13	    private BusinessDay() {
14	    }
15	
16	    /**
17	     * Rolls {@code date} forward to the next Monday when it falls on a weekend; a date that
18	     * already lands on a business day is returned unchanged.
19	     */
20	    public static LocalDate rollForward(LocalDate date) {
21	        DayOfWeek day = date.getDayOfWeek();
22	        if (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY) {
23	            return date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
24	        }
25	        return date;
26	    }
27	}
